'use strict';
const chapters = [
{id:'meet',nav:'Meet the device',kicker:'START WITH THE DEVICE',title:'Meet iPhone Duo.',intro:'Two displays. A hinge. One continuous app. Get to know the space your interface can live in.',idea:'A familiar iPhone.\nA wider canvas.',body:'The outer display keeps everyday tasks close. Open the device and the inner display gives the same app room to show more context. Partially fold it into a book or tabletop pose.',task:'Open the device, fold it into Book pose, then try Portrait. Notice what changes and what stays.',summary:'Start with adaptive navigation',file:'AdaptiveNotes.swift',code:'// Your app supplies the list, detail, and selection.\nNavigationSplitView {\n    NoteList(selection: $selection)\n} detail: {\n    NoteDetail(note: selection)\n}\n// Let the container respond to available space.',note:'NavigationSplitView: iOS 16+. Example app views and selection are placeholders. Build with the iOS 27.1+ SDK for Duo’s full layout and system side bars.',reference:'references/apple-hig-designing-for-iphone-duo.html#1-what-the-device-is',pose:'outer'},
{id:'resize',nav:'Make room',kicker:'01 / AVAILABLE SPACE',title:'Let the layout breathe.',intro:'Start with the space your view actually has. A wider window can reveal more of the same hierarchy.',idea:'Read the view.\nUse the room.',body:'A fixed screen width becomes a stale assumption when the app resizes. A system split view can show a list and detail together, then collapse to the current destination as space gets tighter.',task:'Drag the width down. Compare Adaptive with Fixed width, then give the app more room.',summary:'Size from the current view',file:'AvailableSpace.swift',code:'// UIKit: re-read this during layout.\nlet contentFrame = view.bounds.inset(\n    by: view.safeAreaInsets\n)\n\n// SwiftUI: start with adaptive containers.\nNavigationSplitView {\n    NoteList(selection: $selection)\n} detail: {\n    NoteDetail(note: selection)\n}',note:'Use the actual bounds and each safe-area inset. The browser’s pane budget is a teaching choice; it does not infer iOS traits or device measurements.',reference:'references/apple-hig-designing-for-iphone-duo.html#3-dynamic-layouts',pose:'open'},
{id:'regions',nav:'Respect the fold',kicker:'02 / RESERVED REGIONS',title:'Give the fold its space.',intro:'The hinge changes the usable space inside the view. Keep important controls clear without rebuilding your interface.',idea:'A region to respect.\nA story to preserve.',body:'A partially folded display has a division region. An active inner camera can also reserve an occlusion region. Prefer system containers; use the region frames when laying out custom controls. Scrolling articles and lists can cross the fold.',task:'Switch between Book and Tabletop, then activate the camera. Turn the guides off to see the layout without annotations.',summary:'Query the reserved regions',file:'ReservedRegions.swift',code:'// iOS 27.1+, inside a GeometryReader:\nlet divisions = geometry.reservedRegions(\n    kind: .division\n)\nlet cameras = geometry.reservedRegions(\n    kind: .occlusion\n)\n\n// Inspect each region.frame in this view’s coordinates.\n// Keep custom text and tap targets clear.',note:'Read regions where layout happens and verify updates as the device folds. A fold can change without a resize. Hinge angle is for interactions, not choosing your layout.',reference:'references/apple-hig-designing-for-iphone-duo.html#reserved-regions',pose:'book'},
{id:'bars',nav:'Move the controls',kicker:'03 / SYSTEM CONTAINERS',title:'Let the bars move.',intro:'Keep your actions in the system’s navigation and toolbar containers. Their placement can follow the available space.',idea:'Same actions.\nA different edge.',body:'On the outer display and inner landscape, system bars move to the side. Inner portrait keeps horizontal bars. Labeled, grouped actions can overflow gracefully. A custom bar does not acquire that behavior automatically.',task:'Compare Outer and Portrait. Tap the ••• control in the device to try the illustrative system overflow.',summary:'Give the system your actions',file:'SystemToolbar.swift',code:'NavigationStack {\n    NotesView()\n        .toolbar {\n            ToolbarItemGroup {\n                Button(action: compose) {\n                    Label("Compose",\n                          systemImage: "square.and.pencil")\n                }\n            }\n            .visibilityPriority(.high)\n            ToolbarOverflowMenu {\n                Button("Sort notes", action: sort)\n            }\n        }\n}',note:'ToolbarOverflowMenu and visibilityPriority: iOS 27+. Build with the iOS 27.1+ SDK for Duo side placement. Keep each item’s title and symbol; guard APIs below your deployment target.',reference:'references/apple-hig-designing-for-iphone-duo.html#4-vertical-controls',pose:'outer'},
{id:'state',nav:'Keep the story',kicker:'04 / CONTINUITY',title:'Keep what matters.',intro:'A fold is a change in space during the same task. The selected note and the draft should come along.',idea:'The view adapts.\nThe work stays.',body:'Keep selection and drafts in your app’s model. When the layout changes, show the same content in a shape that fits. Folding full screen does not change scenePhase, so it is not a save-or-recreate signal.',task:'Edit your draft below the diagram, then close and reopen the device. Your words and selection should stay with you.',summary:'Keep state in the model',file:'NotesModel.swift',code:'import Foundation\nimport Observation\n\n@Observable\nfinal class NotesModel {\n    var selectedID: UUID?\n    var draft = ""\n}\n\n// Own this model above the adaptive content.\n// Bind both compact and expanded views to it.\n// Resizing must not recreate or clear the model.',note:'Observation: iOS 17+. This focused pattern shows ownership; persistence across app launches is a separate responsibility. Demo drafts are kept only in this browser’s memory.',reference:'references/apple-hig-designing-for-iphone-duo.html#3-dynamic-layouts',pose:'open'},
{id:'build',nav:'Build your first screen',kicker:'05 / FROM MODEL TO APP',title:'Build your first screen.',intro:'You have the mental model. Check your instincts, then take one real screen through an audit and a device test.',idea:'Start with one screen.\nVerify every transition.',body:'Build with the iOS 27.1 SDK or later. Audit sizing assumptions, use system containers, and test the outer and inner displays, folds, camera regions, narrow windows, and state continuity.',task:'Compare the SDK layouts, check your instincts below, then run the downloadable notes app in Xcode.',summary:'Your first audit',file:'Terminal · from the skill repository root',code:'DUO_AUDIT=skills/iphone-duo-design/scripts/audit_duo_readiness.sh\n\nbash "$DUO_AUDIT" path/to/your/app -s\nbash "$DUO_AUDIT" path/to/your/app -q\n\n# Read every candidate in context.\n# Exit 1 means findings to review; exit 2 is an error.\n# Build and verify on a simulator or device.',note:'The scanner is read-only and needs a local copy of the skill repository. It finds candidates, not confirmed bugs. Browser examples do not replace native testing.',reference:'tutorial.html',pose:'open'}
];
const poseInfo={outer:{label:'OUTER DISPLAY',width:'Compact',bars:'On the side',callout:'Start small. Keep the whole experience.',caption:'The outer display shows the current task, with system controls on the camera’s physical edge.'},open:{label:'INNER · OPEN',width:'Regular',bars:'On the side',callout:'More space. More of the same story.',caption:'The fully open inner landscape display can show a list and its detail together. The fold has no active division gutter.'},book:{label:'INNER · BOOK',width:'Regular',bars:'On the side',callout:'A little space around the fold.',caption:'System split views can balance their panes around the division region. Keep custom controls clear of its frame.'},tabletop:{label:'INNER · TABLETOP',width:'Regular',bars:'Horizontal',callout:'Content above. Interaction within reach.',caption:'This optional arrangement puts content above and supporting controls below the horizontal fold.'},portrait:{label:'INNER · PORTRAIT',width:'Regular',bars:'Horizontal',callout:'Turn the space. Keep the actions.',caption:'Inner portrait is the horizontal-bar exception. Keep actions in their system containers and let placement adapt.'}};
const $=id=>document.getElementById(id);
const scene=$('scene');
let chapterIndex=0,pose='outer',width=760,fragile=false,regions=false,camera=false,selectedNote='adapt',playing=false,tourTimer,toastTimer,lastHash='',currentCode='',sdk='27.1';
const notes={adapt:{title:'Learning\nto adapt.',draft:'Great apps make room for what matters.'},ideas:{title:'Room for\nideas.',draft:'The best idea is the one you can keep working on.'}};
const progressKey='duo-intro-progress-v2';
let savedProgress;
try{savedProgress=JSON.parse(localStorage.getItem(progressKey)||'null');}catch{}
let learning=new DuoLearning.Progress(savedProgress);
const resumeChapter=learning.lastChapter;
let visited=new Set(learning.completed());
const sdkInfo={
 '26':{title:'iOS 26 SDK',layout:'Compatibility layout',bars:'Horizontal',space:'Centered app window',caption:'Built with the iOS 26 SDK: the inner display presents a smaller, centered app window with unused space around it.',callout:'The app runs inside a compatibility window.'},
 '27':{title:'iOS 27.0 SDK',layout:'Expanded layout',bars:'Horizontal',space:'Status-bar edge reserved',caption:'Built with the iOS 27 SDK: the app resizes across most of the inner display, but stops before the status-bar edge.',callout:'More of the display. The status-bar edge stays reserved.'},
 '27.1':{title:'iOS 27.1+ SDK',layout:'Full Duo layout',bars:'On the side',space:'Full inner display',caption:'Built with the iOS 27.1 SDK or later: the app uses the full display and system controls move to the side in inner landscape.',callout:'Full display. System controls follow the available space.'}
};
const escapeHTML=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function highlight(s){return s.split(/(\/\/[^\n]*|#[^\n]*|"(?:\\.|[^"\\])*"|\b(?:let|var|final|class|import|by|kind)\b|\b[A-Z][A-Za-z]+\b)/g).map(t=>{const cls=t.startsWith('//')||t.startsWith('#')?'comment':t.startsWith('"')?'string':/^(let|var|final|class|import|by|kind)$/.test(t)?'keyword':/^[A-Z][A-Za-z]+$/.test(t)?'type':'';return cls?`<span class="token-${cls}">${escapeHTML(t)}</span>`:escapeHTML(t);}).join('');}
function lineBreaks(el,text){el.replaceChildren(...text.split('\n').flatMap((s,i)=>i?[document.createElement('br'),document.createTextNode(s)]:[document.createTextNode(s)]));}
function chapterNav(){
 $('chapters').innerHTML=chapters.map((c,i)=>`<a href="#${c.id}" ${i===chapterIndex?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')}</span><span>${c.nav}</span><span class="chapter-tick">${visited.has(c.id)?'✓':''}</span></a>`).join('');
 $('mobile-chapter').innerHTML=chapters.map((c,i)=>`<option value="${c.id}" ${i===chapterIndex?'selected':''}>${String(i+1).padStart(2,'0')} / ${c.nav}</option>`).join('');$('mobile-progress').textContent=`${visited.size}/6 complete`;
 $('progress-count').textContent=`${visited.size} / 6`;$('journey').value=visited.size;
}
function saveProgress(){try{localStorage.setItem(progressKey,JSON.stringify(learning.snapshot()));}catch{}}
function renderExercise(){
 const id=chapters[chapterIndex].id,steps=DuoLearning.exercises[id],done=learning.steps[id];
 $('exercise-checklist').innerHTML=steps.map(([key,label],i)=>`<li class="${done.has(key)?'done':''}" aria-label="${done.has(key)?'Completed: ':'To try: '}${label}"><span aria-hidden="true">${done.has(key)?'✓':i+1}</span><span>${label}</span></li>`).join('');
 const status=learning.isComplete(id)?'Chapter complete. Keep exploring or continue.':`${done.size} of ${steps.length} checkpoints complete`;
 if($('exercise-status').textContent!==status)$('exercise-status').textContent=status;
}
function recordExercise(event){
 learning.visit(chapters[chapterIndex].id);learning.record(chapters[chapterIndex].id,event);
 visited=new Set(learning.completed());saveProgress();chapterNav();renderExercise();
}

function poseButtons(keys){return `<div class="pose-controls" role="group" aria-label="Display or pose">${keys.map(k=>`<button type="button" data-pose="${k}" aria-pressed="${pose===k}">${k==='open'?'Open':k==='outer'?'Outer':k==='book'?'Book':k==='portrait'?'Portrait':'Tabletop'}</button>`).join('')}<button type="button" class="play-tour" id="play-tour" aria-pressed="false">▷ Animate</button></div>`;}
function renderControls(){
 const id=chapters[chapterIndex].id;
 if(id==='build'){$('experiment-controls').innerHTML=`<div class="sdk-controls" role="group" aria-label="Build SDK comparison">${Object.entries(sdkInfo).map(([key,info])=>`<button type="button" data-sdk="${key}" aria-pressed="${key===sdk}"><span>${info.title}</span><small>${info.layout}</small></button>`).join('')}</div><p class="sdk-explanation">Compare the SDK used to build the app. Your deployment target is a separate choice.</p>`;}
 else if(id==='resize'){$('experiment-controls').innerHTML=`<label class="range-label" for="app-width"><span>Available app width</span><output id="width-output">${width} illustrative units</output></label><input class="width-slider" type="range" min="320" max="900" step="10" value="${width}" id="app-width"><div class="mode-controls" role="group" aria-label="Implementation comparison"><span>Compare</span><button type="button" data-mode="adaptive" aria-pressed="${!fragile}">Adaptive</button><button type="button" data-mode="fragile" aria-pressed="${fragile}">Fixed width</button></div>`;}
 else {$('experiment-controls').innerHTML=poseButtons(id==='regions'?['book','tabletop','open']:id==='state'?['outer','open','book']:id==='bars'?['outer','open','portrait']:['outer','open','book','tabletop','portrait'])+(id==='regions'?'<div class="control-extra"><label><input type="checkbox" id="region-guides" checked> Region guides</label><label><input type="checkbox" id="camera-active"> Inner camera active</label></div>':id==='state'?'<div class="control-extra"><label for="note-choice">Selected note</label><select id="note-choice"><option value="adapt">Learning to adapt</option><option value="ideas">Room for ideas</option></select><span id="draft-count" class="draft-count"></span></div><label class="draft-editor-label" for="draft-editor">Your draft · edit here, then change the pose</label><textarea id="draft-editor" class="draft-editor" rows="2" maxlength="300" spellcheck="false"></textarea>':'');}
 $('experiment-controls').querySelectorAll('[data-pose]').forEach(b=>b.addEventListener('click',()=>{stopTour();setPose(b.dataset.pose,true);}));
 document.querySelectorAll('[data-sdk]').forEach(b=>b.addEventListener('click',()=>{sdk=b.dataset.sdk;updateScene();recordExercise({type:'sdk',sdk});$('try-result').textContent=sdkInfo[sdk].caption;}));
 $('play-tour')?.addEventListener('click',()=>playing?stopTour():startTour());
 $('app-width')?.addEventListener('input',e=>{width=+e.target.value;$('width-output').textContent=`${width} illustrative units`;updateScene();recordExercise({type:'layout',width,fragile});$('try-result').textContent=fragile?'The fixed canvas stays wide while the window narrows. Part of the detail can be clipped.':width<560?'The adaptive layout keeps the selected note and collapses the list.':'With more room, the adaptive layout can show the list alongside its detail.';});
 document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{fragile=b.dataset.mode==='fragile';updateScene();$('try-result').textContent=fragile?'This implementation keeps a 490 CSS pixel canvas even as its window shrinks. Try narrowing it.':'The layout responds to its available space. Your selection stays intact.';recordExercise({type:'layout',width,fragile});}));
 $('region-guides')?.addEventListener('change',e=>{regions=e.target.checked;updateScene();recordExercise({type:'guides',visible:regions});$('try-result').textContent=regions?'Guides reveal the regions. The layout respects them in either state.':'Annotations are hidden. The layout still leaves important controls clear.';});
 $('camera-active')?.addEventListener('change',e=>{camera=e.target.checked;updateScene();recordExercise({type:'camera',active:camera});$('try-result').textContent=camera?'The active inner camera adds an occlusion region. Custom controls must avoid its frame.':'The inner camera region is inactive. The division region still depends on the fold.';});
 if($('draft-editor')){$('draft-editor').value=notes[selectedNote].draft;$('draft-editor').addEventListener('input',e=>{notes[selectedNote].draft=e.target.value;$('note-draft').value=e.target.value;draftUpdated();});}
 if($('note-choice')){$('note-choice').value=selectedNote;$('note-choice').addEventListener('change',e=>selectNote(e.target.value));}
}
function setPose(next,userAction=false){
 if(!poseInfo[next])return;pose=next;updateScene();
 if(userAction){recordExercise({type:'pose',pose,note:selectedNote,text:notes[selectedNote].draft});const id=chapters[chapterIndex].id;$('try-result').textContent=id==='state'?`Still editing “${selectedNote==='adapt'?'Learning to adapt':'Room for ideas'}”. Your ${notes[selectedNote].draft.length} characters stayed with you.`:id==='bars'?`Controls: ${poseInfo[pose].bars.toLowerCase()}. The actions are the same.`:id==='regions'?`${pose==='open'?'No active division region while fully open.':pose==='tabletop'?'A horizontal division separates content and controls.':'A vertical division sits between the panes.'}`:pose==='open'?'The inner display adds context around the same selected note.':pose==='book'?'The panes make room for the division. The current note stays selected.':'Same content and actions. A different amount of space.';}
}
function updateScene(){
 const id=chapters[chapterIndex].id,p=poseInfo[pose],narrow=id==='resize'&&width<560;
 scene.dataset.pose=pose;scene.dataset.chapter=id;scene.dataset.regions=String(regions);scene.dataset.camera=String(camera);scene.dataset.fragile=String(fragile&&id==='resize');scene.dataset.narrow=String(narrow);scene.dataset.sdk=id==='build'?sdk:'27.1';
 scene.style.setProperty('--demo-width',`${53+(width-320)/580*37}%`);
 $('surface-label').textContent=id==='resize'?'RESIZABLE APP WINDOW':p.label;
 $('geometry-label').textContent=id==='build'?sdkInfo[sdk].space.toUpperCase():id==='resize'?`${width} UNITS · ${narrow?'SINGLE DESTINATION':'LIST + DETAIL'}`:`${p.width.toUpperCase()} WIDTH`;
 $('scene-callout').textContent=id==='build'?sdkInfo[sdk].callout:id==='resize'?(fragile?'A fixed canvas runs out of room.':'The layout follows the available space.'):p.callout;
 $('scene-caption').textContent=id==='build'?sdkInfo[sdk].caption:id==='resize'?(fragile?'Fixed width: content stays wider than the narrow window, so part of the detail is clipped.':'Adaptive: show a single destination when narrow, and a list with detail when the pane budget allows.'):p.caption;
 $('state-badge').textContent=id==='build'?sdkInfo[sdk].title:id==='resize'&&fragile?'! Fixed canvas':id==='state'?'● Draft preserved':'● Same app state';
 document.querySelectorAll('[data-sdk]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.sdk===sdk)));
 document.querySelectorAll('#experiment-controls [data-pose]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.pose===pose)));
 document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String((b.dataset.mode==='fragile')===fragile)));
 const facts=id==='resize'?[['Layout',fragile?'Fixed width':narrow?'One destination':'List + detail'],['Sizing',fragile?'Hardcoded canvas':'Available space'],['Selection',selectedNote==='adapt'?'Learning to adapt':'Room for ideas']]:id==='regions'?[['Division',pose==='open'?'Inactive':pose==='tabletop'?'Horizontal':'Vertical'],['Occlusion',camera?'Inner camera active':'Camera inactive'],['Guides',regions?'Visible':'Hidden']]:id==='state'?[['Selected note',selectedNote==='adapt'?'Learning to adapt':'Room for ideas'],['Draft',`${notes[selectedNote].draft.length} characters`],['Ownership','Shared model']]:id==='build'?[['Build SDK',sdkInfo[sdk].title],['System bars',sdkInfo[sdk].bars],['App space',sdkInfo[sdk].space]]:[['Width',p.width],['System bars',p.bars],['App state','Preserved']];
 const tabletopCode='// iOS 27.1+ · optional tabletop arrangement\nNavigationStack {\n    ArrangementView {\n        PlaybackControls()\n    } secondary: {\n        VideoContent()\n    }\n    .arrangementViewStyle(.overlay)\n}\n// Keep navigation around the arrangement.';
 const tabletop=id==='regions'&&pose==='tabletop';
 currentCode=tabletop?tabletopCode:chapters[chapterIndex].code;
 $('swift-code').innerHTML=highlight(currentCode);
 $('code-file').textContent=tabletop?'TabletopArrangement.swift':chapters[chapterIndex].file;
 $('code-summary').textContent=` · ${tabletop?'Let an arrangement handle tabletop':chapters[chapterIndex].summary}`;
 $('code-note').textContent=tabletop?'ArrangementView: iOS 27.1+. An overlay arrangement separates its views around the fold only when partially folded. Example views are placeholders; do not wrap the arrangement in a scrolling container.':chapters[chapterIndex].note;
 $('signal-facts').replaceChildren(...facts.map(([label,value])=>{const div=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;div.append(dt,dd);return div;}));
 if($('draft-count'))$('draft-count').textContent=`${notes[selectedNote].draft.length} characters · in memory`;
}
function showChapter(){
 const aliases={explore:'meet',updates:'build',ship:'build'},raw=location.hash.slice(1),key=aliases[raw]||raw;
 const found=chapters.findIndex(c=>c.id===key);chapterIndex=found<0?0:found;
 const c=chapters[chapterIndex];if($('focus-preview').open)$('focus-preview').close();stopTour();$('resume-banner').hidden=true;if(lastHash||found>=0){learning.visit(c.id);saveProgress();}pose=c.pose;fragile=false;camera=false;regions=c.id==='regions';
 scene.dataset.chapter=c.id;$('chapter-count').textContent=`CHAPTER ${String(chapterIndex+1).padStart(2,'0')} / 06`;$('chapter-kicker').textContent=c.kicker;$('chapter-title').textContent=c.title;$('chapter-intro').textContent=c.intro;$('idea-number').textContent=String(chapterIndex+1).padStart(2,'0');lineBreaks($('idea-title'),c.idea);$('idea-body').textContent=c.body;$('try-text').textContent=c.task;$('try-result').textContent='';$('code-summary').textContent=` · ${c.summary}`;$('code-file').textContent=c.file;$('swift-code').innerHTML=highlight(c.code);$('code-note').textContent=c.note;$('chapter-reference').href=c.reference;$('code-details').open=false;$('previous-chapter').disabled=chapterIndex===0;$('next-chapter').firstElementChild.textContent=chapterIndex===5?'Open guided lab':`Next: ${chapters[chapterIndex+1].nav}`;$('footer-progress').textContent=chapterIndex===0?'One app. Every shape.':`${chapterIndex+1} of 6 chapters`;$('knowledge-check').hidden=c.id!=='build';$('build-resources').hidden=c.id!=='build';$('starter-download').hidden=c.id!=='build';$('system-menu').hidden=true;$('overflow-toggle').setAttribute('aria-expanded','false');
 document.title=`${c.title.replace(/\.$/,'')} — Duo Field Guide`;
 renderControls();chapterNav();updateScene();renderExercise();
 if(lastHash&&lastHash!==key){$('lesson').scrollIntoView({block:'start',behavior:'instant'});$('chapter-title').tabIndex=-1;$('chapter-title').focus({preventScroll:true});}
 lastHash=key||'meet';
 const active=$('chapters').querySelector('[aria-current]');if(active&&matchMedia('(max-width:700px)').matches){const rail=$('chapters');rail.scrollLeft=active.offsetLeft-rail.offsetLeft-14;}
}
function startTour(){
 playing=true;let order=chapters[chapterIndex].id==='regions'?['book','tabletop','open']:chapters[chapterIndex].id==='bars'?['outer','open','portrait']:chapters[chapterIndex].id==='state'?['open','outer','book']:['outer','open','book','tabletop','portrait'];let i=0;
 const delay=matchMedia('(prefers-reduced-motion:reduce)').matches?2400:2000;
 if($('play-tour')){$('play-tour').textContent='Ⅱ Pause';$('play-tour').setAttribute('aria-pressed','true');}
 function tick(){if(!playing)return;setPose(order[i],true);i++;if(i>=order.length){tourTimer=setTimeout(()=>{stopTour();$('try-result').textContent='Tour complete. Choose any pose to explore at your own pace.';},delay);}else tourTimer=setTimeout(tick,delay);}
 tick();
}
function stopTour(){clearTimeout(tourTimer);playing=false;if($('play-tour')){$('play-tour').textContent='▷ Animate';$('play-tour').setAttribute('aria-pressed','false');}}
function selectNote(id){if(!notes[id])return;selectedNote=id;lineBreaks($('note-title'),notes[id].title);$('note-draft').value=notes[id].draft;document.querySelectorAll('[data-note]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.note===id)));if($('note-choice'))$('note-choice').value=id;if($('draft-editor'))$('draft-editor').value=notes[id].draft;updateScene();}
function toast(message){$('intro-toast').textContent=message;$('intro-toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('intro-toast').classList.remove('visible'),3300);}
function draftUpdated(){$('note-status').textContent='Draft updated · in memory';updateScene();if(chapters[chapterIndex].id==='state'){recordExercise({type:'draft',note:selectedNote,text:notes[selectedNote].draft});$('try-result').textContent='Draft updated. Now switch to Outer, then Open. Your words stay in the same model.';}}
$('note-draft').addEventListener('input',e=>{notes[selectedNote].draft=e.target.value;if($('draft-editor'))$('draft-editor').value=e.target.value;draftUpdated();});
$('mobile-chapter').addEventListener('change',e=>location.hash=e.target.value);
 document.querySelectorAll('[data-note]').forEach(b=>b.addEventListener('click',()=>selectNote(b.dataset.note)));
$('compose-note').addEventListener('click',()=>{selectNote('ideas');$('note-draft').focus();toast('Edit “Room for ideas” below. This is a local demo.');});
$('search-note').addEventListener('click',()=>{selectNote(selectedNote==='adapt'?'ideas':'adapt');toast('Switched to the other demo note.');});
$('share-note').addEventListener('click',()=>copyText(notes[selectedNote].draft,'Demo note copied.'));
$('overflow-toggle').addEventListener('click',()=>{const menu=$('system-menu');menu.hidden=!menu.hidden;$('overflow-toggle').setAttribute('aria-expanded',String(!menu.hidden));if(chapters[chapterIndex].id==='bars'){recordExercise({type:'overflow',open:!menu.hidden});$('try-result').textContent='Less frequent actions remain reachable in the overflow. Each item keeps its label.';}});
 document.querySelectorAll('[data-menu]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.menu==='export')copyText(notes[selectedNote].draft,'Demo note copied for export.');else{const list=document.querySelector('.notes-list');const items=[...list.querySelectorAll('[data-note]')];items.reverse().forEach(item=>list.insertBefore(item,list.querySelector('.list-footer')));toast('Demo notes reordered.');}$('system-menu').hidden=true;$('overflow-toggle').setAttribute('aria-expanded','false');}));
 document.addEventListener('click',e=>{if(!e.target.closest('#system-menu')&&!e.target.closest('#overflow-toggle')){$('system-menu').hidden=true;$('overflow-toggle').setAttribute('aria-expanded','false');}});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){stopTour();$('system-menu').hidden=true;$('overflow-toggle').setAttribute('aria-expanded','false');}});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)stopTour();});
$('previous-chapter').addEventListener('click',()=>{if(chapterIndex>0)location.hash=chapters[chapterIndex-1].id;});
$('next-chapter').addEventListener('click',()=>{if(chapterIndex<5)location.hash=chapters[chapterIndex+1].id;else location.href='lab.html';});
function resetProgress(){learning=new DuoLearning.Progress();learning.visit(chapters[chapterIndex].id);visited.clear();quizPassed.clear();quizIndex=0;saveProgress();chapterNav();renderExercise();renderQuiz();$('resume-banner').hidden=true;toast('Learning progress reset. Your current drafts are unchanged.');}
$('reset-progress').addEventListener('click',resetProgress);
$('reset-progress-mobile').addEventListener('click',resetProgress);
async function copyText(text,message){try{await navigator.clipboard.writeText(text);toast(message);}catch{toast('Clipboard unavailable. Select the text and use your browser’s Copy command.');}}
$('copy-code').addEventListener('click',()=>copyText(currentCode,'Swift pattern copied.'));
const quiz=[{q:'The app unfolds while someone is editing. What should decide its layout?',answers:['The current view’s space, safe areas, and traits.','A device-model check and a fixed inner-screen width.','A hinge-angle threshold that creates a new editor.'],correct:0,why:'Use the space you actually have. Preserve the model while the view adapts.'},{q:'A toolbar runs out of room on the side. What should happen to less frequent actions?',answers:['Remove them on the outer display.','Keep them reachable through the system overflow.','Pack every action into one custom view.'],correct:1,why:'Group and label actions in system bars. Use visibility priorities and overflow to preserve access.'},{q:'The device is flat, then partially folded, without a resize. What needs verification?',answers:['That scenePhase became inactive.','That every scrolling list avoids the fold.','That custom controls re-read reserved regions as the fold changes.'],correct:2,why:'A division region can change without resizing. Verify custom layout updates; scenePhase is not a fold callback.'}];
let quizIndex=0,quizPassed=new Set();
function renderQuiz(){const item=quiz[quizIndex];$('quiz-question').textContent=`${quizIndex+1} / 3 — ${item.q}`;$('quiz-options').innerHTML=item.answers.map((a,i)=>`<button type="button" data-answer="${i}" aria-pressed="false">${escapeHTML(a)}</button>`).join('');$('quiz-feedback').textContent='';$('next-question').hidden=true;$('quiz-options').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{const correct=+b.dataset.answer===item.correct;$('quiz-options').querySelectorAll('button').forEach(a=>a.setAttribute('aria-pressed',String(a===b)));$('quiz-feedback').textContent=correct?`Correct. ${item.why}`:`Try again. ${item.why}`;if(correct){quizPassed.add(quizIndex);$('next-question').hidden=false;$('next-question').textContent=quizPassed.size===3?'All three understood ✓':quizIndex===2?'Back to question 1 →':'Next question →';if(quizPassed.size===3){recordExercise({type:'quiz',correctCount:quizPassed.size});$('try-result').textContent='Three concepts checked. Take the next step with a real screen.';}}}));}
$('next-question').addEventListener('click',()=>{if(quizPassed.size===3){$('build-resources').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'center'});return;}quizIndex=(quizIndex+1)%3;renderQuiz();});
const workspace=document.querySelector('.visual-workspace');
const workspaceHome=document.createComment('Live explorer home');
workspace.before(workspaceHome);
$('expand-preview').addEventListener('click',()=>{
 stopTour();$('focus-title').textContent=chapters[chapterIndex].title;
 $('focus-content').append(workspace);$('focus-preview').showModal();
 document.body.classList.add('preview-open');
});
$('close-preview').addEventListener('click',()=>$('focus-preview').close());
$('focus-preview').addEventListener('close',()=>{
 stopTour();workspaceHome.after(workspace);document.body.classList.remove('preview-open');
 $('expand-preview').focus({preventScroll:true});
});
$('resume-course').addEventListener('click',()=>location.hash=resumeChapter);
$('dismiss-resume').addEventListener('click',()=>$('resume-banner').hidden=true);
window.addEventListener('hashchange',()=>{if(location.hash!=='#lesson')showChapter();});renderQuiz();showChapter();
if(!location.hash&&resumeChapter!=='meet'){
 const c=chapters.find(chapter=>chapter.id===resumeChapter);
 if(c){$('resume-description').textContent=`Last chapter: ${c.nav}. ${visited.size} of 6 chapters complete.`;$('resume-banner').hidden=false;}
}

